import { z } from 'zod';
import type { InitializeParams } from './generated/InitializeParams.js';
import type { ThreadStartParams } from './generated/v2/ThreadStartParams.js';
import type { TurnStartParams } from './generated/v2/TurnStartParams.js';
import type { TurnSteerParams } from './generated/v2/TurnSteerParams.js';
import type { TurnInterruptParams } from './generated/v2/TurnInterruptParams.js';
import type { ListMcpServerStatusParams } from './generated/v2/ListMcpServerStatusParams.js';

/** Method parameters are generated by the exact locked app-server binary. */
export interface Parameters {
  initialize: InitializeParams;
  'thread/start': ThreadStartParams;
  'turn/start': TurnStartParams;
  'turn/steer': TurnSteerParams;
  'turn/interrupt': TurnInterruptParams;
  'mcpServerStatus/list': ListMcpServerStatusParams;
}

export const object = z.record(z.string(), z.unknown());
export const message = z.object({
  id: z.union([z.string(), z.number().int()]).optional(),
  method: z.string().optional(),
  params: object.optional(),
  result: z.unknown().optional(),
  error: z.object({ code: z.number().int(), message: z.string() }).passthrough().optional(),
}).passthrough();

export const threadResult = z.object({ thread: z.object({ id: z.string().min(1) }) });
export const turnResult = z.object({ turn: z.object({ id: z.string().min(1) }) });
export const inventoryResult = z.object({ data: z.array(z.unknown()), nextCursor: z.string().nullable() });
export const usage = z.object({
  totalTokens: z.number().int().nonnegative(),
  inputTokens: z.number().int().nonnegative(),
  cachedInputTokens: z.number().int().nonnegative(),
  cacheWriteInputTokens: z.number().int().nonnegative(),
  outputTokens: z.number().int().nonnegative(),
  reasoningOutputTokens: z.number().int().nonnegative(),
});
export type Message = z.infer<typeof message>;

